#ifndef VITALS_MONITOR_DCMD_H
#define VITALS_MONITOR_DCMD_H

#include <devctl.h>
#include <stdint.h>

typedef struct {
    int32_t  value;        /* last value written by a client (e.g. a setpoint) */
    uint32_t flags;
    uint64_t ticks;        /* periodic timer pulses handled so far */
} vitals_monitor_status_t;

/* __DIOF: data from the driver; __DIOT: data to the driver; __DIOTF: both. */
#define DCMD_VITALS_MONITOR_GET_STATUS   __DIOF(_DCMD_MISC, 0x01, vitals_monitor_status_t)
#define DCMD_VITALS_MONITOR_SET_VALUE    __DIOT(_DCMD_MISC, 0x02, int32_t)

#endif

/*
 * vitals_monitorctl.c - tiny client for /dev/vitals_monitor (open + devctl).
 * Generated by QNX Integration Advisor for vitals-monitor. Apache-2.0.
